head.script:
scwin.onpageload = function() {
    scwin.log("page loaded");
};

scwin.log = function(msg) {
    var txa = $p.getComponentById("txa_log");
    var prev = txa.getValue();
    txa.setValue(prev ? prev + "\n" + msg : msg);
};

scwin.btn_test1_onclick = function() {
    scwin.log("=== Test 1: getUri basic path ===");
    var jsLoader = WebSquare.jsLoader;
    var result = jsLoader.getUri("/ui/BM/BM001M01.xml", {parse: true});
    scwin.log("input: /ui/BM/BM001M01.xml");
    scwin.log("output: " + result);
    scwin.log("has //: " + (result.indexOf("/_wpack_//") >= 0 || result.replace(/https?:\/\//, "").indexOf("//") >= 0));
};

scwin.btn_test2_onclick = function() {
    scwin.log("=== Test 2: getUri with origin ===");
    var jsLoader = WebSquare.jsLoader;
    var input = location.origin + "/ui/BM/BM001M01.xml";
    var result = jsLoader.getUri(input, {parse: true});
    scwin.log("input: " + input);
    scwin.log("output: " + result);
    var stripped = result.replace(/https?:\/\//, "");
    scwin.log("has //: " + (stripped.indexOf("//") >= 0));
};

scwin.btn_test3_onclick = function() {
    scwin.log("=== Test 3: getUri w2xPath encoded ===");
    var jsLoader = WebSquare.jsLoader;
    var input = "?w2xPath=%2Fui%2FBM%2FBM001M01.xml";
    var result = jsLoader.getUri(input, {parse: true});
    scwin.log("input: " + input);
    scwin.log("output: " + result);
    scwin.log("has //: " + (result.replace(/https?:\/\//, "").indexOf("//") >= 0));
};

scwin.btn_test4_onclick = function() {
    scwin.log("=== Test 4: getUri trailing slash path ===");
    var jsLoader = WebSquare.jsLoader;
    var input = "/ui//BM/BM001M01.xml";
    var result = jsLoader.getUri(input, {parse: true});
    scwin.log("input: " + input);
    scwin.log("output: " + result);
    var stripped = result.replace(/https?:\/\//, "");
    scwin.log("has //: " + (stripped.indexOf("//") >= 0));
};

scwin.btn_runall_onclick = function() {
    $p.getComponentById("txa_log").setValue("");
    scwin.btn_test1_onclick();
    scwin.btn_test2_onclick();
    scwin.btn_test3_onclick();
    scwin.btn_test4_onclick();
    scwin.log("\n=== ALL TESTS DONE ===");
};
